import{_ as o,o as t,c as a,a5 as i}from"./chunks/framework.BjM_ivYE.js";const n="/RBQ/images/app/home-audio.pc.en.png",m=JSON.parse('{"title":"Audio (walkie-talkie)","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/audio.md","filePath":"manual/gui/audio.md","lastUpdated":1790646319000}'),r={name:"manual/gui/audio.md"};function s(d,e,h,l,c,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="audio-walkie-talkie" tabindex="-1">Audio (walkie-talkie) <a class="header-anchor" href="#audio-walkie-talkie" aria-label="Permalink to &quot;Audio (walkie-talkie)&quot;">​</a></h1><p>The robot carries a speaker and a microphone. The <code>Audio</code> tool on the control home turns the app into a walkie-talkie: listen to what the robot hears, and hold a button to talk through its speaker.</p><h2 id="opening-the-popover" tabindex="-1">Opening the popover <a class="header-anchor" href="#opening-the-popover" aria-label="Permalink to &quot;Opening the popover&quot;">​</a></h2><p>Tap <code>Audio</code> (the microphone icon) in the right card (<code>OBSERVE</code>). The popover is titled <code>Walkie-talkie</code> <code>· Robot speaker/mic</code>. A green dot on the <code>Audio</code> button means listening is currently on.</p><p><img src="'+n+'" alt="Walkie-talkie popover"></p><h2 id="listening" tabindex="-1">Listening <a class="header-anchor" href="#listening" aria-label="Permalink to &quot;Listening&quot;">​</a></h2><p><code>Listen to robot audio</code> is a toggle. Switch it on and the robot&#39;s microphone streams to your device until you switch it off. The label under it reads <code>Listening</code> or <code>Off</code>. Listening stays on when you close the popover — the dot on the <code>Audio</code> button reminds you.</p><h2 id="volume" tabindex="-1">Volume <a class="header-anchor" href="#volume" aria-label="Permalink to &quot;Volume&quot;">​</a></h2><p>Three sliders, each showing its value in percent (defaults 80 / 70 / 65 %):</p><table tabindex="0"><thead><tr><th>Slider</th><th>Controls</th></tr></thead><tbody><tr><td><code>Robot speaker</code></td><td>Loudness of your voice out of the robot.</td></tr><tr><td><code>Robot mic</code></td><td>Gain of the robot&#39;s microphone (what you hear when listening).</td></tr><tr><td><code>My volume</code></td><td>Playback level on your own device.</td></tr></tbody></table><p>The app stores the last values you set and restores them on the next start.</p><h2 id="push-to-talk" tabindex="-1">Push to talk <a class="header-anchor" href="#push-to-talk" aria-label="Permalink to &quot;Push to talk&quot;">​</a></h2><p>Talking is not in the popover. Press and <strong>hold</strong> the <code>Walkie-talkie</code> button at the bottom right of the control home — next to the right joystick, or at the right edge when a gamepad is connected. While you hold it the button turns green and reads <code>Talking</code>. Release it to stop. The app sends your voice only while you hold the button, so nothing goes out by accident — the popover&#39;s footer reminds you: <code>To talk, hold [Walkie-talkie] at the bottom right</code>.</p><p>The first time you press the button the app asks for microphone permission. If you refuse (or no microphone can be opened), the <code>Walkie-talkie</code> button turns amber and the popover&#39;s footer changes to <code>No mic permission — allow it in app settings</code>. Grant it in the operating system&#39;s app settings and try again.</p><h2 id="robot-speaker-power" tabindex="-1">Robot speaker power <a class="header-anchor" href="#robot-speaker-power" aria-label="Permalink to &quot;Robot speaker power&quot;">​</a></h2><p>If the robot&#39;s speaker amplifier is switched off you will see <code>Robot speaker power is off</code> in the popover, and the <code>Walkie-talkie</code> button is dimmed and cannot be pressed. Tap <code>Turn on</code> in that banner to power the amplifier and talk again.</p><h2 id="platform-notes" tabindex="-1">Platform notes <a class="header-anchor" href="#platform-notes" aria-label="Permalink to &quot;Platform notes&quot;">​</a></h2><ul><li><strong>Audio channel</strong> — <code>Robot audio channel failed — check the robot connection</code> in the footer means the audio link to the robot could not be set up. Check that the robot is connected (video is streaming) and press <code>Walkie-talkie</code> again.</li><li><strong>Choosing your own speaker/microphone</strong> — only when the app runs in a web browser: a <code>My devices</code> block lists <code>Speaker (output)</code> and <code>Microphone (applies from next PTT)</code>. Each list appears only when the browser reports devices of that kind, and the speaker list also needs a browser that supports output switching — Chrome does, some others do not. If no device has a name yet (Device 1, Device 2…), tap <code>Show device names — allow mic permission</code>. The Android, iOS, and desktop apps use whatever audio devices the system is on, so this block is hidden.</li><li><strong><code>My mic</code> <code>Send gain</code></strong> — shown only in browsers that still support a microphone volume constraint. Current Chrome does not, so most people never see it.</li></ul>',18)])])}const k=o(r,[["render",s]]);export{m as __pageData,k as default};
